previewCss:
.darma-loader-darma-b7-atom-orbit { --accent: var(--loader-color, #f472b6); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; }
.darma-loader-darma-b7-atom-orbit::before { content: ''; position: absolute; left: 50%; top: 50%; width: 16%; height: 16%; margin: -8% 0 0 -8%; border-radius: 50%; background: var(--accent); box-shadow: 0 0 calc(var(--loader-size, 84px) * .14) var(--accent); }
.darma-loader-darma-b7-atom-orbit span { position: absolute; left: 8%; right: 8%; top: 35%; bottom: 35%; border: calc(var(--loader-size, 84px) * .025) solid color-mix(in srgb, var(--accent-2) 40%, transparent); border-radius: 50%; }
.darma-loader-darma-b7-atom-orbit span::after { content: ''; position: absolute; top: 50%; left: 0; width: calc(var(--loader-size, 84px) * .12); height: calc(var(--loader-size, 84px) * .12); margin-top: calc(var(--loader-size, 84px) * -.06); border-radius: 50%; background: var(--accent-2); }
.darma-loader-darma-b7-atom-orbit span:nth-child(1) { animation: darma-loader-darma-b7-atom-orbit-orbit-a calc(var(--loader-speed, 1s) * 1.8) linear infinite; }
.darma-loader-darma-b7-atom-orbit span:nth-child(2) { animation: darma-loader-darma-b7-atom-orbit-orbit-b calc(var(--loader-speed, 1s) * 2.2) linear infinite; }
.darma-loader-darma-b7-atom-orbit span:nth-child(3) { animation: darma-loader-darma-b7-atom-orbit-orbit-c calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
@keyframes darma-loader-darma-b7-atom-orbit-orbit-a { to { rotate: 360deg; } }
@keyframes darma-loader-darma-b7-atom-orbit-orbit-b { from { rotate: 120deg; } to { rotate: 480deg; } }
@keyframes darma-loader-darma-b7-atom-orbit-orbit-c { from { rotate: 240deg; } to { rotate: 600deg; } }

